def kanal(c):
    c = c / 255
    if c <= 0.04045:
        return c / 12.92
    return ((c + 0.055) / 1.055) ** 2.4

def leucht(hexfarbe):
    h = hexfarbe.lstrip("#")
    r, g, b = (kanal(int(h[i:i+2], 16))
               for i in (0, 2, 4))
    return 0.2126*r + 0.7152*g + 0.0722*b

def kontrast(f1, f2):
    a, b = sorted([leucht(f1),
                   leucht(f2)])
    return (b + 0.05) / (a + 0.05)

for f in ("#000000", "#767676",
          "#777777", "#FF0000"):
    print(f, round(kontrast(
        f, "#FFFFFF"), 2))
# #000000 21.0
# #767676 4.54  -> AA ok
# #777777 4.48  -> AA knapp nicht
# #FF0000 4.0   -> nur großer Text

